import{_ as d,c as e,o,am as c}from"./chunks/framework.BJtUKP3U.js";const p=JSON.parse('{"title":"绘制阶段与高级布局","description":"","frontmatter":{"prev":{"text":"内部动作","link":"/docs/pogget/custom-vina/actions"},"next":{"text":"内置文案","link":"/docs/pogget/custom-vina/labels"}},"headers":[],"relativePath":"docs/pogget/custom-vina/slots.md","filePath":"docs/pogget/custom-vina/slots.md"}'),a={name:"docs/pogget/custom-vina/slots.md"};function r(i,t,n,l,h,s){return o(),e("div",null,t[0]||(t[0]=[c(`<h1 id="绘制阶段与高级布局" tabindex="-1">绘制阶段与高级布局 <a class="header-anchor" href="#绘制阶段与高级布局" aria-label="Permalink to &quot;绘制阶段与高级布局&quot;">​</a></h1><p><code>type</code> 选择图元，<code>slot</code> 选择宿主何时绘制该视图。修改原有标题、文件项目或编辑器时，先找到标准预设的对应组件，保留必要的阶段和元数据，再覆盖目标属性。</p><p>一个 slot 不是一套固定外观。它的子节点仍使用<a href="./reference.html">通用图元和属性</a>，布局与颜色可以自行声明。以下列出当前标准场景的全部 <strong>45 个 slot</strong>。</p><h2 id="标题与窗口" tabindex="-1">标题与窗口 <a class="header-anchor" href="#标题与窗口" aria-label="Permalink to &quot;标题与窗口&quot;">​</a></h2><table tabindex="0"><thead><tr><th><code>slot</code></th><th>用途</th></tr></thead><tbody><tr><td><code>containerFrame</code></td><td>整盒收尾阶段，绘制最终边框、玻璃/光效和标签着色；客户区像素尺寸通过 <code>scale</code> 换算</td></tr><tr><td><code>titleSurface</code></td><td>标题表面、背景、边框、阴影、分隔线</td></tr><tr><td><code>titleCollapse</code></td><td>折叠按钮的绘制、几何与动作</td></tr><tr><td><code>titleMore</code></td><td>更多菜单按钮</td></tr><tr><td><code>titlePin</code></td><td>悬停展开后的固定按钮</td></tr><tr><td><code>titlePinBackground</code></td><td>固定按钮胶囊的背景</td></tr><tr><td><code>titlePinHotzone</code></td><td>固定按钮胶囊的悬停区域，使用通用 <code>hoverRegion</code></td></tr><tr><td><code>titleTag</code></td><td>标题标签表面与文字</td></tr><tr><td><code>titleTab</code></td><td>合并收纳盒的每个标签页，逐项提交 <code>pogget.tab.*</code></td></tr><tr><td><code>titleSearchSurface</code></td><td>标题搜索框的外部表面</td></tr><tr><td><code>titleSearchInput</code></td><td>搜索输入框皮肤，<code>editor</code> 元数据同步文字测量与输入命中</td></tr><tr><td><code>titleSearchOptions</code></td><td>搜索选项按钮</td></tr><tr><td><code>inlineSearchSurface</code></td><td>内联搜索界面与返回/取消的表面、占位布局</td></tr><tr><td><code>inlineSearchBack</code></td><td>内联搜索返回按钮</td></tr><tr><td><code>inlineSearchCancel</code></td><td>内联搜索取消按钮</td></tr></tbody></table><h2 id="文件项目" tabindex="-1">文件项目 <a class="header-anchor" href="#文件项目" aria-label="Permalink to &quot;文件项目&quot;">​</a></h2><table tabindex="0"><thead><tr><th><code>slot</code></th><th>用途</th></tr></thead><tbody><tr><td><code>fileIconSurface</code></td><td>每个文件项目的背景、选中与悬停表面</td></tr><tr><td><code>fileIconContent</code></td><td>Shell 图标、文件夹条目预览、媒体缩略图与拖入提示</td></tr><tr><td><code>fileIconText</code></td><td>文件名布局策略的根阶段，提供 <code>textLayout</code> 和 <code>gridLayout</code></td></tr><tr><td><code>fileIconTitle</code></td><td>列表等普通标题阶段</td></tr><tr><td><code>fileIconDetail</code></td><td>列表大小、日期等详情文字阶段</td></tr><tr><td><code>fileGridTitle</code></td><td>普通网格和媒体文件名</td></tr><tr><td><code>fileSearchHighlight</code></td><td>每个搜索命中片段的高亮背景</td></tr><tr><td><code>fileSearchTitle</code></td><td>使用原生命中文本布局绘制搜索文件名</td></tr><tr><td><code>filePreview</code></td><td>文本/Markdown 预览卡片、正文、页脚与标题</td></tr><tr><td><code>fileIconMotion</code></td><td>整个图标/拖动虚影的运动与动画策略，不是可见的背景层</td></tr><tr><td><code>fileGhostSurface</code></td><td>列表拖动虚影的额外底板，也接入声明式虚影绘制</td></tr></tbody></table><p>例如只修改标准文件项目表面的某个子节点，仍需在 <code>FileIconSurface.view</code> 的既有路径下覆盖。新增无 slot 的组件不会自动按文件数量重复；不要在普通组件里读取最后一次提交的 <code>fileIcon.*</code> 来模拟重复列表。</p><h2 id="内联内容与工具栏" tabindex="-1">内联内容与工具栏 <a class="header-anchor" href="#内联内容与工具栏" aria-label="Permalink to &quot;内联内容与工具栏&quot;">​</a></h2><table tabindex="0"><thead><tr><th><code>slot</code></th><th>用途</th></tr></thead><tbody><tr><td><code>inlineContentSurface</code></td><td>内联文件夹/编辑器遮罩、背景与布局元数据</td></tr><tr><td><code>inlineContentSnapshot</code></td><td>退出/切换快照的裁切、缩放、不透明度与模糊</td></tr><tr><td><code>inlineNavigationSurface</code></td><td>内联导航和编辑工具栏的整体表面与显隐策略</td></tr><tr><td><code>inlineNavigationBack</code></td><td>后退按钮</td></tr><tr><td><code>inlineNavigationHome</code></td><td>退出内联文件夹、回主页的按钮</td></tr><tr><td><code>inlineNavigationSave</code></td><td>内联编辑保存按钮</td></tr><tr><td><code>inlineNavigationOpen</code></td><td>用外部程序打开当前编辑文件的按钮</td></tr><tr><td><code>inlineNavigationSearch</code></td><td>内联搜索开关按钮</td></tr></tbody></table><h2 id="markdown-编辑器与分页" tabindex="-1">Markdown 编辑器与分页 <a class="header-anchor" href="#markdown-编辑器与分页" aria-label="Permalink to &quot;Markdown 编辑器与分页&quot;">​</a></h2><table tabindex="0"><thead><tr><th><code>slot</code></th><th>用途</th></tr></thead><tbody><tr><td><code>markdownEditorSurface</code></td><td>多行编辑器背景与边框</td></tr><tr><td><code>markdownEditorPlaceholder</code></td><td>占位文字</td></tr><tr><td><code>markdownEditorSelection</code></td><td>根据真实字形矩形绘制选区片段</td></tr><tr><td><code>markdownEditorContent</code></td><td>同步正文内容资源</td></tr><tr><td><code>markdownEditorCaret</code></td><td>光标</td></tr><tr><td><code>markdownEditorScrollbars</code></td><td>双轴滚动条</td></tr><tr><td><code>markdownEditorZoomHint</code></td><td>缩放提示</td></tr><tr><td><code>markdownEditorViewport</code></td><td>可选共享视口，统一选区、正文和光标的裁剪、原点与缩放</td></tr><tr><td><code>pageIndicatorSurface</code></td><td>分页指示器根阶段与重复点数策略</td></tr><tr><td><code>pageIndicatorDot</code></td><td>每个普通分页点</td></tr><tr><td><code>pageIndicatorActive</code></td><td>活动分页标记</td></tr></tbody></table><h3 id="完整接管与回退" tabindex="-1">完整接管与回退 <a class="header-anchor" href="#完整接管与回退" aria-label="Permalink to &quot;完整接管与回退&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>接管要求与边界</th></tr></thead><tbody><tr><td>内联导航</td><td><code>inlineNavigationSurface</code> 加 Back、Home、Save、Open、Search 五个按钮 slot 全部存在；不完整时使用整套原生工具栏</td></tr><tr><td>内联内容</td><td><code>inlineContentSurface</code> 与 <code>inlineContentSnapshot</code> 配合，旧/不完整声明保留原生背景和快照路径</td></tr><tr><td>Markdown 皮肤</td><td>Surface、Placeholder、Selection、Content、Caret、Scrollbars、ZoomHint 七阶段完整；缺少时保留整套原生皮肤</td></tr><tr><td>Markdown 共享视口</td><td>可选 <code>markdownEditorViewport</code> 组中必须有唯一的同名 <code>content</code> 资源；使用原生 <code>zoom</code> 作为独立输入</td></tr><tr><td>分页指示器</td><td>Surface、Dot、Active 三阶段与 <code>repeat.count</code> 完整；不完整时使用原生指示器</td></tr><tr><td>文件文字与预览</td><td>对应根 slot 和测量策略共同决定接入；缺少时保留对应原生阶段</td></tr><tr><td>整盒收尾</td><td>缺少 <code>containerFrame</code> 时保留原生绘制；已声明但隐藏时主动隐藏该阶段；非法帧会请求原生回退</td></tr></tbody></table><p>原生仍负责文件资源、拖放排序、编辑、IME、撤销、动画触发和生命周期。Markdown 语义内的表格、代码、图片等样式仍由原生处理。</p><h2 id="动画与布局元数据" tabindex="-1">动画与布局元数据 <a class="header-anchor" href="#动画与布局元数据" aria-label="Permalink to &quot;动画与布局元数据&quot;">​</a></h2><p>以下块是宿主读取的布局/动画策略，不会生成额外绘制或点击节点。<strong>同名字段在不同块下含义不同，必须放在表中指定的路径。</strong> 依赖模式可只覆盖需要修改的项；从零声明时，应参照标准预设保留完整策略。</p><h3 id="标题组件的-motion" tabindex="-1">标题组件的 motion <a class="header-anchor" href="#标题组件的-motion" aria-label="Permalink to &quot;标题组件的 motion&quot;">​</a></h3><p>位置是组件下的 <code>motion</code>，例如 <code>TitleSurface.motion</code>，不在 <code>view</code> 中。</p><table tabindex="0"><thead><tr><th>字段</th><th>用途与范围</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>是否使用声明式折叠进度目标</td></tr><tr><td><code>targetProgress</code></td><td>折叠进度目标，由宿主限制到 <code>0..1</code></td></tr><tr><td><code>duration</code></td><td>折叠时长，<code>0..10</code> 秒，默认 <code>0.4</code></td></tr><tr><td><code>transitionDuration</code>、<code>searchDuration</code></td><td>标题样式切换、搜索展开时长，<code>0..10</code> 秒，默认均为 <code>0.4</code></td></tr><tr><td><code>searchFrom</code>、<code>searchTo</code></td><td>搜索展开起止值，±256，默认 <code>-4</code>、<code>0</code></td></tr><tr><td><code>targetX</code>、<code>targetY</code></td><td>目标位置，±32768</td></tr><tr><td><code>targetWidth</code>、<code>targetHeight</code>、<code>targetRadius</code></td><td>目标宽、高、圆角，<code>0..32768</code></td></tr><tr><td><code>targetShadowY</code></td><td>目标阴影纵偏移，±256</td></tr><tr><td><code>targetShadowAlpha</code>、<code>targetBorderAlpha</code></td><td>目标阴影、边框不透明度，<code>0..1</code></td></tr></tbody></table><h3 id="titletab-的-view-motion" tabindex="-1">titleTab 的 view.motion <a class="header-anchor" href="#titletab-的-view-motion" aria-label="Permalink to &quot;titleTab 的 view.motion&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>用途与范围</th></tr></thead><tbody><tr><td><code>x</code>、<code>y</code>、<code>width</code>、<code>height</code></td><td>当前标签目标矩形；坐标 ±32768，尺寸 <code>0..32768</code></td></tr><tr><td><code>islandX</code>、<code>islandY</code>、<code>islandWidth</code>、<code>islandHeight</code></td><td>标签背景岛矩形，范围同上</td></tr><tr><td><code>islandRadius</code></td><td>背景岛圆角，<code>0..32768</code></td></tr><tr><td><code>nextX</code></td><td>下一个成员的横向布局游标，±32768</td></tr><tr><td><code>stripX</code>、<code>stripWidth</code></td><td>标签条起点和宽度，分别为 ±32768、<code>0..32768</code></td></tr><tr><td><code>weight</code></td><td>当前成员布局权重，<code>0..32768</code>；宿主累计权重供分配宽度</td></tr><tr><td><code>contentReserve</code>、<code>titleExtension</code></td><td>内容区、标题的附加占位，<code>0..32768</code></td></tr><tr><td><code>minimumHeight</code>、<code>collapsedGap</code></td><td>显示门槛高度与折叠间距，<code>0..32768</code></td></tr><tr><td><code>hoverDuration</code>、<code>unhoverDuration</code></td><td>悬停进入/离开时长，<code>0..10</code> 秒</td></tr><tr><td><code>selectionDuration</code>、<code>deselectionDuration</code></td><td>选中/取消选中时长，<code>0..10</code> 秒</td></tr><tr><td><code>layoutDuration</code></td><td>布局过渡时长，<code>0..10</code> 秒</td></tr></tbody></table><h3 id="titlesearchinput-的-editor" tabindex="-1">titleSearchInput 的 editor <a class="header-anchor" href="#titlesearchinput-的-editor" aria-label="Permalink to &quot;titleSearchInput 的 editor&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>用途与范围</th></tr></thead><tbody><tr><td><code>padding</code></td><td>文字测量与命中的内边距，<code>0..32768</code></td></tr><tr><td><code>textSize</code></td><td>测量字号，<code>1..256</code></td></tr><tr><td><code>font</code></td><td>非空字体族，最多 256 个字符</td></tr><tr><td><code>caretDuration</code></td><td>光标动画周期参数，<code>0.001..10</code> 秒</td></tr></tbody></table><p>文字的绘制字号和布局测量应保持一致，避免点击位置、选区和 IME 坐标错位。</p><h3 id="inlinesearchsurface-的-motion" tabindex="-1">inlineSearchSurface 的 motion <a class="header-anchor" href="#inlinesearchsurface-的-motion" aria-label="Permalink to &quot;inlineSearchSurface 的 motion&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>用途与范围</th></tr></thead><tbody><tr><td><code>backSurfaceX</code>、<code>cancelSurfaceX</code>、<code>surfaceY</code></td><td>返回、取消按钮表面的横坐标和共同纵坐标，±32768</td></tr><tr><td><code>surfaceWidth</code></td><td>按钮表面宽度，<code>0..32768</code></td></tr><tr><td><code>backButtonX</code>、<code>cancelButtonX</code>、<code>buttonY</code></td><td>返回、取消按钮坐标，±32768</td></tr><tr><td><code>searchX</code>、<code>searchY</code>、<code>searchWidth</code></td><td>搜索框位置与宽度，坐标 ±32768、宽度 <code>0..32768</code></td></tr><tr><td><code>resultsExtraY</code></td><td>结果区增加的纵向占位，<code>0..32768</code></td></tr><tr><td><code>usesSecondRow</code></td><td>布尔；窄窗口是否使用第二行布局</td></tr></tbody></table><p>这 12 个字段需要完整提供。</p><h3 id="fileicontext-的-textlayout-与-gridlayout" tabindex="-1">fileIconText 的 textLayout 与 gridLayout <a class="header-anchor" href="#fileicontext-的-textlayout-与-gridlayout" aria-label="Permalink to &quot;fileIconText 的 textLayout 与 gridLayout&quot;">​</a></h3><table tabindex="0"><thead><tr><th>块与字段</th><th>用途与范围</th></tr></thead><tbody><tr><td><code>textLayout.titleWidth</code></td><td>列表标题测量宽度，<code>0..32768</code></td></tr><tr><td><code>textLayout.titleSize</code>、<code>textLayout.detailSize</code></td><td>标题、详情测量字号，<code>1..256</code></td></tr><tr><td><code>textLayout.font</code></td><td>标题/详情字体族，非空且最多 256 字符</td></tr><tr><td><code>textLayout.omitOffset</code></td><td>省略预算偏移，±32768</td></tr><tr><td><code>textLayout.omitScale</code></td><td>省略预算比例，<code>0.001..256</code></td></tr><tr><td><code>textLayout.measureDetail</code></td><td>布尔；是否测量详情宽度</td></tr><tr><td><code>gridLayout.width</code>、<code>gridLayout.textSize</code></td><td>网格标题测量宽度与字号，分别 <code>0..32768</code>、<code>1..256</code></td></tr><tr><td><code>gridLayout.font</code></td><td>网格标题字体族</td></tr><tr><td><code>gridLayout.centered</code>、<code>gridLayout.wrap</code></td><td>布尔；是否居中、是否换行</td></tr><tr><td><code>gridLayout.interactionWidth</code>、<code>gridLayout.interactionTextSize</code></td><td>提前测量悬停溢出的宽度与字号，范围同网格标题</td></tr><tr><td><code>gridLayout.searchHeight</code></td><td>搜索标题测量高度预算，<code>0..32768</code></td></tr></tbody></table><h3 id="filepreview-的-previewlayout" tabindex="-1">filePreview 的 previewLayout <a class="header-anchor" href="#filepreview-的-previewlayout" aria-label="Permalink to &quot;filePreview 的 previewLayout&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>用途与范围</th></tr></thead><tbody><tr><td><code>excerptUnits</code></td><td>摘要的 Unicode 显示单位预算，整数 <code>1..32768</code>，必需</td></tr><tr><td><code>titleWidth</code></td><td>预览标题测量宽度，<code>0..32768</code></td></tr><tr><td><code>titleSize</code></td><td>标题测量字号，<code>0.001..256</code></td></tr><tr><td><code>titleFont</code></td><td>标题字体族</td></tr><tr><td><code>titleWrap</code></td><td>布尔；标题是否换行</td></tr></tbody></table><h3 id="fileiconmotion-的-motion-与-animation" tabindex="-1">fileIconMotion 的 motion 与 animation <a class="header-anchor" href="#fileiconmotion-的-motion-与-animation" aria-label="Permalink to &quot;fileIconMotion 的 motion 与 animation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>块与字段</th><th>用途与范围</th></tr></thead><tbody><tr><td><code>motion.x</code>、<code>motion.y</code></td><td>整体位置，±32768</td></tr><tr><td><code>motion.scaleX</code>、<code>motion.scaleY</code></td><td>整体横纵缩放，<code>0.001..8</code></td></tr><tr><td><code>motion.pivotX</code>、<code>motion.pivotY</code></td><td>缩放中心，±32768</td></tr><tr><td><code>motion.active</code></td><td>布尔；是否应用整体运动；上述七项需完整提供</td></tr><tr><td><code>animation.hoverDuration</code>、<code>animation.unhoverDuration</code></td><td>原生悬停进出时长，<code>0..10</code> 秒</td></tr><tr><td><code>animation.pressDuration</code>、<code>animation.releaseDuration</code></td><td>按压/释放时长，<code>0..10</code> 秒</td></tr><tr><td><code>animation.rightPressDuration</code>、<code>animation.rightReleaseDuration</code></td><td>右键按压/回弹时长，<code>0..10</code> 秒</td></tr><tr><td><code>animation.rightPush</code></td><td>右键按压目标进度，<code>0..1</code></td></tr></tbody></table><h3 id="inlinenavigationsurface-的-motion" tabindex="-1">inlineNavigationSurface 的 motion <a class="header-anchor" href="#inlinenavigationsurface-的-motion" aria-label="Permalink to &quot;inlineNavigationSurface 的 motion&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>用途与范围</th></tr></thead><tbody><tr><td><code>hideOffset</code>、<code>showOffset</code></td><td>隐藏、显示目标偏移，±32768</td></tr><tr><td><code>duration</code></td><td>显隐时长，<code>0..10</code> 秒</td></tr><tr><td><code>scrollDelta</code></td><td>触发显隐的滚动变化阈值，<code>0..32768</code></td></tr><tr><td><code>pointerArea</code></td><td>指针触发显示的区域阈值，<code>0..32768</code></td></tr><tr><td><code>topThreshold</code></td><td>顶部显示阈值，<code>0..32768</code></td></tr></tbody></table><p>这六项需要完整提供。</p><h3 id="inlinecontentsurface-的-hostlayout" tabindex="-1">inlineContentSurface 的 hostLayout <a class="header-anchor" href="#inlinecontentsurface-的-hostlayout" aria-label="Permalink to &quot;inlineContentSurface 的 hostLayout&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>用途与范围</th></tr></thead><tbody><tr><td><code>editorX</code>、<code>editorY</code></td><td>原生编辑器输入矩形的位置，±32768</td></tr><tr><td><code>editorWidth</code>、<code>editorHeight</code></td><td>编辑器输入矩形尺寸，<code>0..32768</code></td></tr><tr><td><code>iconsX</code></td><td>图标管理器横坐标，±32768，向零截断为整数</td></tr><tr><td><code>iconsY</code></td><td>包含滚动的图标管理器纵坐标，±1073741823，向零截断为整数</td></tr><tr><td><code>layoutWidth</code></td><td>原生排列测量宽度，<code>0..32768</code>，按整数使用</td></tr><tr><td><code>viewportWidth</code>、<code>viewportHeight</code></td><td>资源加载与绘制视口尺寸，<code>0..32768</code></td></tr><tr><td><code>iconsAlpha</code></td><td>图标不透明度，<code>0..1</code></td></tr><tr><td><code>viewTop</code>、<code>viewBottom</code></td><td>可见范围上下边界，±32768</td></tr><tr><td><code>cullMargin</code>、<code>expansionMargin</code></td><td>剔除余量、展开余量，<code>0..32768</code></td></tr></tbody></table><p>这 14 项作为完整布局提供。它们同时影响输入矩形、测量和资源加载，不只是绘图位置。</p><h3 id="inlinecontentsurface-的-animation" tabindex="-1">inlineContentSurface 的 animation <a class="header-anchor" href="#inlinecontentsurface-的-animation" aria-label="Permalink to &quot;inlineContentSurface 的 animation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>用途与范围</th></tr></thead><tbody><tr><td><code>enterDuration</code>、<code>exitDuration</code>、<code>switchDuration</code></td><td>进入、退出、层级切换时长，<code>0..10</code> 秒</td></tr><tr><td><code>enterX1</code>、<code>enterY1</code>、<code>enterX2</code>、<code>enterY2</code></td><td>进入动画三次贝塞尔控制点，均为 <code>0..1</code></td></tr><tr><td><code>exitX1</code>、<code>exitY1</code>、<code>exitX2</code>、<code>exitY2</code></td><td>退出动画控制点，均为 <code>0..1</code></td></tr><tr><td><code>switchX1</code>、<code>switchY1</code>、<code>switchX2</code>、<code>switchY2</code></td><td>层级切换动画控制点，均为 <code>0..1</code></td></tr></tbody></table><p>这 15 项作为完整策略提供。原生负责触发、取消和快照生命周期。</p><h3 id="inlinecontentsurface-的-editor" tabindex="-1">inlineContentSurface 的 editor <a class="header-anchor" href="#inlinecontentsurface-的-editor" aria-label="Permalink to &quot;inlineContentSurface 的 editor&quot;">​</a></h3><p>这是 Markdown 多行编辑器的几何策略，与搜索框的 <code>editor</code> 不同。全部字段及非空 <code>font</code> 需要完整提供。</p><table tabindex="0"><thead><tr><th>字段</th><th>用途与范围</th></tr></thead><tbody><tr><td><code>padding</code>、<code>margin</code></td><td>编辑器内边距、测量边距，<code>0..2048</code></td></tr><tr><td><code>contentWidth</code>、<code>contentHeight</code></td><td>内容可用宽高，<code>1..32768</code></td></tr><tr><td><code>baseHeight</code></td><td>不扣除横向滚动条时的基础高度，<code>1..32768</code></td></tr><tr><td><code>layoutWidth</code></td><td>排版测量宽度，<code>1..65536</code></td></tr><tr><td><code>font</code>、<code>textSize</code></td><td>测量字体族和字号，字号 <code>1..256</code>，字体最多 256 字符</td></tr><tr><td><code>verticalTrack</code>、<code>verticalThumb</code></td><td>纵向滚动条轨道、滑块长度，<code>0..32768</code>，滑块不大于轨道</td></tr><tr><td><code>horizontalTrack</code>、<code>horizontalThumb</code></td><td>横向滚动条轨道、滑块长度，范围同上</td></tr><tr><td><code>verticalHitLeft</code>、<code>verticalHitTop</code>、<code>verticalHitRight</code>、<code>verticalHitBottom</code></td><td>纵向滚动条命中边界，±32768</td></tr><tr><td><code>horizontalHitLeft</code>、<code>horizontalHitTop</code>、<code>horizontalHitRight</code>、<code>horizontalHitBottom</code></td><td>横向滚动条命中边界，±32768</td></tr><tr><td><code>caretDuration</code>、<code>zoomHintDuration</code></td><td>光标动画、缩放提示时长，<code>0.001..10</code> 秒</td></tr><tr><td><code>scrollDuration</code>、<code>zoomDuration</code></td><td>滚动、缩放时长，<code>0..10</code> 秒</td></tr></tbody></table><h3 id="pageindicatorsurface-的-repeat" tabindex="-1">pageIndicatorSurface 的 repeat <a class="header-anchor" href="#pageindicatorsurface-的-repeat" aria-label="Permalink to &quot;pageIndicatorSurface 的 repeat&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>用途与范围</th></tr></thead><tbody><tr><td><code>count</code></td><td><code>repeat { count: ... }</code> 声明实际绘制的普通点数量，整数 <code>0..256</code>；可与真实页数不同</td></tr></tbody></table><p>宿主只按此数量提交 <code>pageIndicatorDot</code>，将序号放入 <code>pogget.pageIndicator.index</code>，最后绘制 Active。点数上限、间距、边缘缩小和活动标记几何均由预设计算。</p><h2 id="命名资源" tabindex="-1">命名资源 <a class="header-anchor" href="#命名资源" aria-label="Permalink to &quot;命名资源&quot;">​</a></h2><p>资源仅在对应同步绘制中可用，缺少时不画。资源名不是文件路径，也不是允许调用的函数名。</p><table tabindex="0"><thead><tr><th>资源名</th><th>配套类型与用途</th></tr></thead><tbody><tr><td><code>thumbnail</code></td><td><code>image</code> + <code>imageRenderer: &quot;resource&quot;</code>；当前文件缩略图/媒体封面</td></tr><tr><td><code>fileTitle</code></td><td><code>text</code> + <code>textRenderer: &quot;resource&quot;</code>；搜索命中的原生文件名布局</td></tr><tr><td><code>markdown</code></td><td><code>content</code>；当前文件的 Markdown 预览正文</td></tr><tr><td><code>inlineExit</code>、<code>inlineSwitch</code></td><td><code>image</code> + <code>imageRenderer: &quot;resource&quot;</code>；内联退出、层级切换快照</td></tr><tr><td><code>markdownEditor</code></td><td><code>content</code>；当前多行编辑器正文</td></tr><tr><td><code>markdownEditorViewport</code></td><td><code>content</code>；调度编辑器共享视口内的选区、正文和光标；同名 slot 内只能声明一个</td></tr></tbody></table><h2 id="header-兼容布局" tabindex="-1">Header 兼容布局 <a class="header-anchor" href="#header-兼容布局" aria-label="Permalink to &quot;Header 兼容布局&quot;">​</a></h2><p><code>pogget.native.Header</code> 只调整已有标题控件的位置，保留原生点击、长按和菜单。一个预设最多声明一个 Header。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Preset { dependsOn: &quot;Pogget_Std&quot; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>HeaderLayout {</span></span>
<span class="line"><span>  vars {</span></span>
<span class="line"><span>    tagWidth: \${pogget.titleTextWidth} + 58,</span></span>
<span class="line"><span>    tagLeft: (\${pogget.width} - \${vars.tagWidth}) / 2</span></span>
<span class="line"><span>  },</span></span>
<span class="line"><span>  view {</span></span>
<span class="line"><span>    type: &quot;pogget.native.Header&quot;,</span></span>
<span class="line"><span>    tagX: \${vars.tagLeft}, tagY: 6,</span></span>
<span class="line"><span>    tagWidth: \${vars.tagWidth}, tagHeight: 28,</span></span>
<span class="line"><span>    moreX: \${vars.tagLeft} + \${vars.tagWidth} - 22,</span></span>
<span class="line"><span>    moreY: 18</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段</th><th>用途</th></tr></thead><tbody><tr><td><code>tagAlign</code></td><td><code>&quot;left&quot;</code> 或 <code>&quot;center&quot;</code>；标题标签的兼容对齐方式</td></tr><tr><td><code>tagX</code>、<code>tagY</code></td><td>标签横纵位置，±32768</td></tr><tr><td><code>tagWidth</code>、<code>tagHeight</code></td><td>标签尺寸，<code>0..32768</code></td></tr><tr><td><code>moreX</code>、<code>moreY</code></td><td>更多按钮位置，±32768</td></tr><tr><td><code>collapseX</code>、<code>collapseY</code></td><td>折叠按钮位置，±32768</td></tr></tbody></table><h3 id="旧布局映射字段" tabindex="-1">旧布局映射字段 <a class="header-anchor" href="#旧布局映射字段" aria-label="Permalink to &quot;旧布局映射字段&quot;">​</a></h3><p>标准视图节点上的下列元数据把 Header 的字段映射到普通视图。通常保留标准声明，只覆盖 Header；新布局可以直接修改普通节点。</p><table tabindex="0"><thead><tr><th>字段</th><th>用途</th></tr></thead><tbody><tr><td><code>legacyX</code>、<code>legacyY</code>、<code>legacyWidth</code>、<code>legacyHeight</code></td><td>指定 Header 中用于覆盖节点相应几何的字段名</td></tr><tr><td><code>legacyOriginX</code>、<code>legacyOriginY</code>、<code>legacyOriginWidth</code>、<code>legacyOriginHeight</code></td><td>对兼容覆盖值增加的原点/尺寸补偿</td></tr><tr><td><code>legacyExtraWidth</code></td><td>宽度覆盖的额外补偿</td></tr><tr><td><code>legacyAlignX</code></td><td>指定 Header 横向对齐字段；值为 <code>center</code> 时参与居中计算</td></tr><tr><td><code>legacyCenterWidth</code></td><td>未从 Header 指定宽度时的居中宽度</td></tr></tbody></table><p>映射先整体校验再发布，移除 Header 覆盖会恢复普通视图声明。本页根据当前 <code>VinaView.hpp</code>、<code>VinaMarkdownGeometry.hpp</code>、运行时接入点和 <code>Pogget_Std.vina</code> 核对（2026-11-08）。</p>`,60)]))}const b=d(a,[["render",r]]);export{p as __pageData,b as default};
